(function(api){const fs=api.fs,basePath=api.basePath,bankPath=basePath+"CARAVAN_SFX.BIN",indexPath=basePath+"CARAVAN_SFX.IDX",previewPath=basePath+"CARAVAN_SFX_PLAY.WAV";let removed=0,previewTimer=0,previewActive=0,previewDone=0;function u32(data,offset){return(data.charCodeAt(offset)&255)+((data.charCodeAt(offset+1)&255)<<8)+((data.charCodeAt(offset+2)&255)<<16)+((data.charCodeAt(offset+3)&255)*16777216)}function clearPreviewTimer(){if(previewTimer){clearTimeout(previewTimer);previewTimer=0}}function info(clip,level){let f=0,row,offset,length;if(removed)throw new Error("SFX ENGINE REMOVED");if(clip<0||clip>5||level<1||level>15)throw new Error("SFX INDEX RANGE");try{f=E.openFile(indexPath,"r");if(!f)throw new Error("SFX INDEX OPEN");f.seek((clip*16+level)*8);row=f.read(8);if(!row||row.length!==8)throw new Error("SFX INDEX READ");offset=u32(row,0);length=u32(row,4);if(!length||length<94)throw new Error("SFX INDEX EMPTY");if(f.close)f.close();f=0}catch(error){try{if(f&&f.close)f.close()}catch(closeError){}throw error}return[offset,length]}function readPayload(clip,level,startBlock,blockCount){let meta=info(clip,level),f=0,start=startBlock||0,total=meta[1]-94,bytes,data;if(start<0)throw new Error("SFX BLOCK START");bytes=blockCount?blockCount*256:total-start*256;if(bytes<=0||start*256+bytes>total)throw new Error("SFX BLOCK RANGE");try{f=E.openFile(bankPath,"r");if(!f)throw new Error("SFX BANK OPEN");f.seek(meta[0]+94+start*256);data=f.read(bytes);if(!data||data.length!==bytes)throw new Error("SFX BANK READ");if(f.close)f.close();f=0}catch(error){try{if(f&&f.close)f.close()}catch(closeError){}throw error}return data}function copyPreview(clip,level){let meta=info(clip,level),input=0,output=0,left=meta[1],part;try{input=E.openFile(bankPath,"r");if(!input)throw new Error("SFX BANK OPEN");output=E.openFile(previewPath,"w");if(!output)throw new Error("SFX PREVIEW OPEN");input.seek(meta[0]);while(left>0){part=input.read(left>1024?1024:left);if(!part||!part.length)throw new Error("SFX PREVIEW READ");if(output.write(part)!==part.length)throw new Error("SFX PREVIEW WRITE");left-=part.length}if(input.close)input.close();input=0;if(output.close)output.close();output=0}catch(error){try{if(input&&input.close)input.close()}catch(closeError){}try{if(output&&output.close)output.close()}catch(closeError){}throw error}return meta}function previewDuration(meta){let blocks=Math.floor((meta[1]-94)/256);return Math.ceil(blocks*31.5625)+120}function finishPreview(){let cb=previewDone;previewTimer=0;previewActive=0;previewDone=0;if(cb)cb()}function startPreview(clip,level,onStart,onDone){let meta;stopPreview();if(removed||level<=0)return 0;try{meta=copyPreview(clip,level);previewDone=onDone||0;Pip.audioStart(previewPath);previewActive=1;if(onStart)onStart();previewTimer=setTimeout(finishPreview,previewDuration(meta));return 1}catch(error){previewDone=0;previewActive=0;clearPreviewTimer();try{Pip.audioStop()}catch(stopError){}return 0}}function stopPreview(){let was=previewActive||previewTimer;clearPreviewTimer();if(was)try{Pip.audioStop()}catch(error){}previewActive=0;previewDone=0}function remove(){if(removed)return;stopPreview();removed=1}return{info:info,readPayload:readPayload,startPreview:startPreview,stopPreview:stopPreview,isPreviewing:function(){return previewActive?1:0},bankPath:bankPath,remove:remove}});